{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "seek a higher general cap"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "a lower de minimis, aggregation of connected claims, and a tipping basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer general warranty period, for example 24 months"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Separate protection, ordinarily at least the purchase price cap; no general basket/de minimis; materially longer survival"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Express, appropriately drafted carve-outs from contractual protections for the responsible party; preserve non-excludable rights"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Prefer specific disclosures; tightly constrain any general disclosure."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete the constructive-knowledge exclusion."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "A Buyer-benefit condition precedent covering effective consent under clauses 11.2 and 11.3, with evidence that all conditions are satisfied."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "a binding simultaneous repayment-and-release mechanism at Completion"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "allocate transaction-triggered bonuses and applicable employer on-costs to the Seller"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "A specific indemnity covering losses arising from the identified payment/title defect—not merely the invoice amount—with tailored limits and survival."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a tailored indemnity for the pre-Completion incident and related reasonable investigation, remediation and third-party liabilities"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "ordinary future operating expenditure should not automatically reduce price. Accrued liabilities, unusual commitments, covenant breaches or Seller-driven costs may warrant adjustment or specific protection."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "reject blanket “all Claims” limitations, blanket disclosure and constructive Buyer knowledge; separate fundamental, tax and specific-indemnity regimes."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "the register supports Harbourglass’s recorded holding but does not alone establish unencumbered, transferable ownership or absence of options and competing rights."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "require a dedicated pre-Completion tax allocation/indemnity and appropriate warranties, claim procedures and survival."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

